function (state) {
  const shadow = (color, size, offset=0) => {
    return `
    text-shadow: 
      -${size}px -${size}px ${Math.random() * offset}px ${color},
       ${size}px -${size}px ${Math.random() * offset}px ${color},
      -${size}px ${size}px ${Math.random() * offset} ${color},
       ${size}px ${size}px ${Math.random() * offset}px ${color};`
  }

  let f = num => (Math.round(num * 100) / 100).toFixed(2);
  let size = sig(1.2)
  let c = sig(1)
  let mul = sig(1.5)
  let onmousemove = e => {
    let bbox = e.target.getBoundingClientRect()
    let x = e.clientX - bbox.x
    let y =  e.clientY - bbox.y
    let w = bbox.width
    let h_ = bbox.height
    c.set(x/w)
    mul.set(1 + 2*y/h_)
  }

  let style = mem(() => `
   background-color: white;
   border-radius: 100px;
   color: white;
   background-size: 20px 20px;
   background-image:
    linear-gradient(to right, #0002 1px, transparent 1px),
    linear-gradient(to bottom, #0002 1px, transparent 1px); 

   font-size: ${size()}em;
   filter:  blur(${c()*2}px);
   box-shadow: 0 0 ${f(size() * c() * 2)}px ${f(c() * c() * 2)}px #0004;
   ${shadow("blue", f(size() * mul()))}`
  )

  let parent = `
    width:100%;
    height:100%;
    background: #ddd;
    cursor: crosshair;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;

   background-size: 80px 60px;
   background-image:
    linear-gradient(to right, #0002 1px, transparent 1px),
    linear-gradient(to bottom, #0002 1px, transparent 1px); 
  `

  let dom = mem(() => 
    style().split(`\n`).map((e) => 
      h("p", {style}, e)
    ))

  return  h("div",{style:parent, onmousemove}, dom )
}
